  return ["STAR69AI — CUSTOM DEMO PRESENTATION BRIEF","Prospect: "+value(r.contact_name)+" ("+value(r.email)+")","Business: "+value(r.business_name),"Industry: "+value(r.industry),"Suggested opening: Thank you for calling "+value(r.business_name)+". This is the virtual receptionist. How may I help you?","","DISCOVERY SNAPSHOT","Website: "+value(x.website),"Service area: "+value(x.serviceArea),"Services: "+value(x.services),"Hours: "+value(x.hours),"Call volume: "+value(x.callVolume),"Caller tasks: "+value(x.callTasks),"FAQs: "+value(x.faqs),"Human escalation preference: "+value(x.humanEscalation),"Prospect plan interest: "+value(x.planInterest),"Requested features:\n"+requested,"","SUGGESTED INDUSTRY CALL SCENARIOS",...scenariosFor(r.industry).map((v,i)=>(i+1)+". "+v),"","EXPECTED DEMO PROMPT CONTENT",...configured.map(v=>"- "+v),"","NOT CONNECTED OR ACTIVATED BY DEMO CREATION","- Production phone number or live call routing","- Calendar or appointment booking integration","- CRM, dispatch or business software integration","- SMS, outbound calling, email delivery or live transfer tools unless separately configured and verified","- Customer account, subscription or production activation","","CURRENT PUBLISHED PLAN OPTIONS",...planLines,"One-time setup fee: $99, invoiced separately.","Plan and pricing are discussion references, not a binding quote. Confirm the current checkout and written terms before making an offer.","NEXT STEP","Review and test the demo agent, then present the configured capabilities and limitations clearly. Mark the demo as presented only after it has actually been shown to the prospect."].join("\n");
